/* Ajoute le catalogue à la boutique du profil ouvert (une seule fois par profil et par version du catalogue). Appelée à la connexion. */
function seedStore(force) {
  try {
    if (!SESSION || !D || !G) return 0;
    if (!force && typeof pendingPull === 'function' && pendingPull(SESSION.user.id)) return 0;   // profil importé : après la récupération des données du cloud
    const present = G.store.concat(G.apps).some(a => /^w-/.test(String(a.id)));   // une récupération depuis le cloud peut remplacer la boutique par une ancienne sauvegarde sans le catalogue : on le remet
    if (!force && D.seed === SEED_VER && present) return 0;
    const slug = s => s.normalize('NFD').replace(/[^a-zA-Z0-9]+/g, '-').replace(/^-+|-+$/g, '').toLowerCase();
    const all = G.store.concat(G.apps), names = new Set(all.map(a => String(a.name || '').toLowerCase())), urls = new Set(all.map(a => a.url).filter(Boolean)), ids = new Set(all.map(a => a.id));
    // mise à jour du catalogue : seules les NOUVELLES entrées sont ajoutées (celles que vous avez supprimées ne reviennent pas) ; D.seedN = nombre d'entrées déjà proposées
    const from = !force && present ? (Number.isInteger(D.seedN) ? Math.min(D.seedN, SEED_APPS.length) : D.seed === '2026-11-web5' ? 705 : 0) : 0;
    let n = 0;
    for (const [name, url, cat, desc, ai] of SEED_APPS.slice(from)) {
      if (G.store.length >= 10000) break;   // limite de la boutique
      const id = 'w-' + slug(name);
      if (ids.has(id) || names.has(name.toLowerCase()) || urls.has(url)) continue;
      G.store.push({ id, name, url, lc: '', ex: '', ap: '', cat, desc, mode: 'auto', img: new URL(url).origin + '/favicon.ico', ai: ai === 1 });
      n++;
    }
    D.seed = SEED_VER; D.seedN = SEED_APPS.length; saveG(); save();
    if (n) { toast(n + ' application' + (n > 1 ? 's' : '') + ' web ajoutée' + (n > 1 ? 's' : '') + ' à l’App Store (onglet « Apps cloud »).', 6000); try { if (typeof refresh === 'function') refresh(); } catch { /* fenêtre fermée */ } }
    return n;
  } catch { return 0; /* sans conséquence : réessayé à la prochaine connexion */ }
}
